package com.enterprise.quality;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.logging.Level;
import java.util.logging.Logger;

public class SecureDataAccessor {

    private static final Logger LOGGER = Logger.getLogger(SecureDataAccessor.class.getName());
    private static final String QUERY = "SELECT username FROM users WHERE id = ?";

    // SonarQube compliant: Uses PreparedStatement to prevent SQL Injection
    // and proper try-with-resources to prevent resource leaks.
    public String fetchUsername(String jdbcUrl, String userId) {
        try (Connection conn = DriverManager.getConnection(jdbcUrl);
             PreparedStatement stmt = conn.prepareStatement(QUERY)) {

            stmt.setString(1, userId);
            try (ResultSet rs = stmt.executeQuery()) {
                if (rs.next()) {
                    return rs.getString("username");
                }
            }
        } catch (SQLException e) {
            LOGGER.log(Level.SEVERE, "Database error occurred during user lookup", e);
        }
        return null;
    }
}
